import{z as l,x as o,o as B,c as p,q as n,j as s,D as e,d as A,s as t,S as r,b as a}from"./chunks/framework.C8m1ZpeB.js";const T=JSON.parse('{"title":"启发式与偏差","description":"","frontmatter":{"title":"启发式与偏差","date":"2026-09-08T00:00:00.000Z","section":"econ"},"headers":[],"relativePath":"econ/heuristics-biases.md","filePath":"econ/heuristics-biases.md","lastUpdated":1791413859000}'),d={name:"econ/heuristics-biases.md"};function m(F,E,c,u,h,D){const i=o("Mermaid");return B(),p("div",null,[E[2]||(E[2]=n('<h1 id="启发式与偏差" tabindex="-1">启发式与偏差 <a class="header-anchor" href="#启发式与偏差" aria-label="Permalink to &quot;启发式与偏差&quot;">​</a></h1><div class="epigraph"><p>代表性、可得性、锚定：用便宜的线索代替概率计算，偏差是捷径的影子，不是随机噪声。</p><footer>—— Tversky and Kahneman, Judgment under Uncertainty: Heuristics and Biases, Science, 1974</footer></div><p><a href="/econ/overconfidence">上一课</a>给出校准失败。本课缺口是机制：人用启发式生成概率，于是系统性地偏。不把过度自信再定义一遍。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>贝叶斯要求似然与先验。Tversky 与 Kahneman（1974）列出三条捷径。代表性：用「像不像典型」代替基率与样本量，导致基率忽视、合取谬误。可得性：用容易想起的例子代替频率，媒体暴露扭曲灾难概率。锚定与调整：从任意起点调整不足，估计依赖无关锚。这些偏差不是对 <a href="/econ/expected-utility">vNM</a> 的再拒绝，而是对信念输入的拒绝。</p><p>家庭金融：用近期回报代表未来（代表性）制造趋势追逐；用身边炒股故事代表参与收益（可得性）；用买入价当锚（与参考点重叠但起源是判断而非偏好）。</p><p><span class="marginnote">数字实例：1000 人里只有 5 名工程师、995 名护士，某人的描述极像工程师（似然比按 10:1 算）。贝叶斯后验是 \\(5\\times10/(50+995)\\approx 5\\%\\)；依赖代表性的人会报出 80% 以上——基率被整段替换掉了。</span></p><p><span class="marginnote">合取谬误：Linda 是银行出纳且女权主义者，被判比「银行出纳」更可能。概率上不可能，代表性上更像故事。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>实验：基率问题、字母频率、轮盘给出的锚。预测是方向性的：锚高则估计高，生动事件则概率高。本课不估计启发式的神经基础。与概率加权的分工：加权是已知 \\(p\\) 仍扭曲；启发式是 \\(p\\) 本身被错估。</p>',10)),(B(),s(r,null,{default:e(()=>[t(i,{id:"mermaid-28",class:"mermaid",graph:"flowchart%20TD%0A%20%20OC%5B%22%E8%BF%87%E5%BA%A6%E8%87%AA%E4%BF%A1%3A%20%E7%B2%BE%E5%BA%A6%E8%BF%87%E9%AB%98%22%5D%20--%3E%20H%5B%22%E5%90%AF%E5%8F%91%E5%BC%8F%3A%20%E7%94%A8%E7%BA%BF%E7%B4%A2%E4%BB%A3%E6%9B%BF%E8%B4%9D%E5%8F%B6%E6%96%AF%22%5D%0A%20%20H%20--%3E%20REP%5B%22%E4%BB%A3%E8%A1%A8%E6%80%A7%3A%20%E5%BF%BD%E8%A7%86%E5%9F%BA%E7%8E%87%22%5D%0A%20%20H%20--%3E%20AV%5B%22%E5%8F%AF%E5%BE%97%E6%80%A7%3A%20%E7%94%9F%E5%8A%A8%E4%BB%A3%E6%9B%BF%E9%A2%91%E7%8E%87%22%5D%0A%20%20H%20--%3E%20ANC%5B%22%E9%94%9A%E5%AE%9A%3A%20%E8%B0%83%E6%95%B4%E4%B8%8D%E8%B6%B3%22%5D%0A"})]),fallback:e(()=>[...E[0]||(E[0]=[A(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=a("h2",{id:"机制",tabindex:"-1"},[A("机制 "),a("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),E[4]||(E[4]=a("p",null,"机制是属性替换：目标属性难算，用启发属性代替。偏差因此可预测，可被框架放大（生动描述提高可得性）。资产价格若由使用同一启发式的人加总，会有动量与反转——BSV 用代表性与保守性写模型，后单元再接。本课只给微观判断。",-1)),E[5]||(E[5]=a("p",null,"与有限理性的接口：启发式可以是对计算成本的最优响应（后课 Simon），也可以是固定的心理程序。1974 年论文取后者：偏差相对规范模型被定义。",-1)),E[6]||(E[6]=a("p",null,[a("span",{class:"marginnote"},"术语翻译：锚定与调整=先抓一个手边数字当起点（哪怕来自随机轮盘），再不够力气地往上修。起点与问题无关却仍把最终估计拽偏，这就是「调整不足」。")],-1)),(B(),s(r,null,{default:e(()=>[t(i,{id:"mermaid-41",class:"mermaid",graph:"flowchart%20TD%0A%20%20Q%5B%22%E7%9B%AE%E6%A0%87%E9%97%AE%E9%A2%98%3A%20P(%E7%B1%BB%E5%88%AB%7C%E8%AF%81%E6%8D%AE)%20%E6%98%AF%E5%A4%9A%E5%B0%91%3F%22%5D%20--%3E%20HARD%5B%22%E6%A6%82%E7%8E%87%E8%AE%A1%E7%AE%97%E5%8F%88%E6%85%A2%E5%8F%88%E8%B4%B5%22%5D%0A%20%20HARD%20--%3E%20SUB%5B%22%E5%B1%9E%E6%80%A7%E6%9B%BF%E6%8D%A2%3A%20%E6%94%B9%E9%97%AE%20'%E8%AF%81%E6%8D%AE%E5%83%8F%E4%B8%8D%E5%83%8F%E5%85%B8%E5%9E%8B'%22%5D%0A%20%20SUB%20--%3E%20FAST%5B%22%E5%90%AF%E5%8F%91%E5%B1%9E%E6%80%A7%3A%20%E7%9B%B8%E4%BC%BC%E5%BA%A6%2F%E6%98%93%E6%83%B3%E8%B5%B7%E7%A8%8B%E5%BA%A6%2F%E8%B5%B7%E7%82%B9%E9%94%9A%22%5D%0A%20%20FAST%20--%3E%20OUT%5B%22%E7%AD%94%E5%BE%97%E5%BF%AB%2C%20%E4%BD%86%E6%96%B9%E5%90%91%E7%B3%BB%E7%BB%9F%E5%9C%B0%E5%81%8F%22%5D%0A%20%20OUT%20--%3E%20B%5B%22%E5%9F%BA%E7%8E%87%E8%A2%AB%E5%8E%8B%E4%BD%8E%2C%20%E7%94%9F%E5%8A%A8%E4%BA%8B%E4%BB%B6%E8%A2%AB%E6%8A%AC%E9%AB%98%2C%20%E4%BC%B0%E8%AE%A1%E8%B4%B4%E7%9D%80%E9%94%9A%22%5D%0A"})]),fallback:e(()=>[...E[1]||(E[1]=[A(" Loading... ",-1)])]),_:1})),E[7]||(E[7]=n('<p>基率忽视不是把先验设成无信息：人往往用代表性完全替换贝叶斯分子分母里的基率。锚定的起点可以无关（随机轮盘），调整不足使估计继承锚——这与买入价参考点近亲，但起源是判断数字，不是得失编码。可得性让最近的崩盘故事抬高主观尾部，保险需求上升，不必先动 \\(w(p)\\)。BSV 后课会把代表性与保守写成价格动态。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>Gigerenzer 强调生态理性：在正确环境下启发式可以更准。本栏补层仍用规范贝叶斯当对照，否则「偏差」没有定义。现场经验、统计培训能减弱部分效应，不能据此宣称市场无偏差。本课不把三条写成完备分类。</p><p><span class="marginnote">常见误区：把偏差当成随机误差，以为样本一大平均掉就没事。恰恰相反——偏差是同方向、可预测的，平均不会消掉它，只会让整个市场的总量偏得更整齐。</span></p><p>后课默认：判断偏差来自启发式；有限理性给出「为何不用完整贝叶斯」的计算理由。</p><p>属性替换生成可预测偏差：代表性压基率，可得性用生动代替频率，锚定调整不足。</p><p>与概率加权分工：启发式错估输入，加权扭曲已知 \\(p\\)。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>代表性、可得性、锚定系统性地错估 \\(p\\)。</li><li>与概率加权分工：一个错估输入，一个扭曲已知 \\(p\\)。</li><li>不重推期望效用；信念侧的缺口在此。</li><li>合取谬误是代表性的经典。</li><li>BSV 后课把代表性与保守放进价格。</li><li>出处：Tversky and Kahneman, <em>Science</em> 1974。</li></ul>',9))])}const _=l(d,[["render",m]]);export{T as __pageData,_ as default};
